import { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { postJson } from '../../api/http';
import { PersonCells, PersonColumnHead } from '../../slots/defs/personRow';
import { peopleKey, usePeople, type Person } from '../people/usePeople';
import { poolsKey } from '../pools/usePools';
import { usePersonRowAction } from '../people/usePersonRowAction';
import { Col } from '../columns/useColumns';

/** A person's holds: whether they have any, a line per hold (from – to), and a from-date (blank: the
 *  sheet's today), an optional to-date (blank: open-ended) and a button that adds a hold. Their open
 *  (OPEN or PENDING) claims dated within a hold, unless bound by a statement, count in no live total;
 *  their other claims still do. A hold ends on its to-date. */
function PersonHold({ sheetId, personId }: { sheetId: string; personId: number }) {
  const people = usePeople(sheetId);
  const queryClient = useQueryClient();
  const p = people.data?.find((x) => x.id === personId);
  const [from, setFrom] = useState('');
  const [to, setTo] = useState('');

  const hold = useMutation({
    mutationFn: (body: { from: string; to: string }) =>
      postJson<Person>(`/api/sheets/${encodeURIComponent(sheetId)}/people/${personId}/hold`, body),
    onSuccess: async () => {
      setFrom('');
      setTo('');
      await queryClient.invalidateQueries({ queryKey: peopleKey(sheetId) });
      // A hold in force on the sheet's today takes the person's cuts from the pools.
      void queryClient.invalidateQueries({ queryKey: poolsKey(sheetId) });
    },
  });
  const announce = usePersonRowAction(sheetId, personId, hold.reset);

  return (
    <>
      <Col id="hold"><td data-testid="person-hold">{p?.held ? 'yes' : 'no'}</td></Col>
      <td>
        {(p?.holds ?? []).map((h, i) => (
          <div key={i} data-testid="person-hold-line">
            {h.from ?? ''} – {h.to ?? ''}
          </div>
        ))}
      </td>
      <td>
        <input
          type="text"
          placeholder="from yyyy-mm-dd"
          data-testid="person-hold-from"
          value={from}
          onChange={(e) => {
            setFrom(e.target.value);
            hold.reset();
          }}
        />{' '}
        <input
          type="text"
          placeholder="to yyyy-mm-dd"
          data-testid="person-hold-to"
          value={to}
          onChange={(e) => {
            setTo(e.target.value);
            hold.reset();
          }}
        />{' '}
        <button
          type="button"
          data-testid="person-hold-toggle"
          disabled={hold.isPending}
          onClick={() => {
            announce();
            hold.reset();
            hold.mutate({ from: from.trim(), to: to.trim() });
          }}
        >
          Hold
        </button>
        {hold.isError && <span data-testid="person-error">{hold.error.message}</span>}
      </td>
    </>
  );
}

export const contributions = [
  PersonColumnHead.fill({
    order: 45,
    Component: () => (
      <>
        <Col id="hold"><th>Held</th></Col>
        <th>Holds</th>
        <th />
      </>
    ),
  }),
  PersonCells.fill({ order: 45, Component: PersonHold }),
];
import { useEffect, useId } from 'react';

// The actions on a person's row (statement, hold, retire) live in separate slots, but share the row's one
// `person-error`. Taking any of them announces it on the row, and every other action there clears its old
// error, so a refusal left by one action never shows beside (or for) the next.
const bus = new EventTarget();

/** Clear this action's error (`reset`) when another action on the same row is taken; returns the
 *  `announce` to call as this action is taken. */
export function usePersonRowAction(sheetId: string, personId: number, reset: () => void): () => void {
  const self = useId();
  const row = `${sheetId}/${personId}`;
  useEffect(() => {
    const listener = (e: Event) => {
      const d = (e as CustomEvent<{ row: string; from: string }>).detail;
      if (d.row === row && d.from !== self) reset();
    };
    bus.addEventListener('person-action', listener);
    return () => bus.removeEventListener('person-action', listener);
  }, [row, self, reset]);
  return () => bus.dispatchEvent(new CustomEvent('person-action', { detail: { row, from: self } }));
}
